// Patches generated by real git (diff -U0 / default context, --no-renames).
const (
	realMultiHunkU0 = `diff --git a/f.txt b/f.txt
index 1c99002..516acad 100644
--- a/f.txt
+++ b/f.txt
@@ -0,0 +1 @@
+zero
@@ -3 +4 @@
-3
+three
@@ -10,0 +12,2 @@
+ins1
+ins2
@@ -20 +22,0 @@
-20
@@ -30,2 +31,0 @@
-30
-31
@@ -38,0 +39 @@
+tail
`
	realMultiHunkU3 = `diff --git a/f.txt b/f.txt
index 1c99002..516acad 100644
--- a/f.txt
+++ b/f.txt
@@ -1,6 +1,7 @@
+zero
 1
 2
-3
+three
 4
 5
 6
@@ -8,6 +9,8 @@
 8
 9
 10
+ins1
+ins2
 11
 12
 13
@@ -17,7 +20,6 @@
 17
 18
 19
-20
 21
 22
 23
@@ -27,8 +29,6 @@
 27
 28
 29
-30
-31
 32
 33
 34
@@ -36,5 +36,6 @@
 36
 37
 38
+tail
 39
 40
`
	realDeletedU0 = `diff --git a/d.txt b/d.txt
deleted file mode 100644
index 01e79c3..0000000
--- a/d.txt
+++ /dev/null
@@ -1,3 +0,0 @@
-1
-2
-3
diff --git a/k.txt b/k.txt
deleted file mode 100644
index b68fde2..0000000
--- a/k.txt
+++ /dev/null
@@ -1 +0,0 @@
-k
`
)

func TestParseRealMultiHunkPatches(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name           string
		patch          string
		files          int
		added, deleted int
	}{
		{"U0 hunks, zero-count sides", realMultiHunkU0, 1, 5, 4},
		{"default context hunks", realMultiHunkU3, 1, 5, 4},
		{"deleted files at U0", realDeletedU0, 2, 0, 4},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			d, err := ParseUnifiedDiff(tt.patch)
			if err != nil {
				t.Fatalf("ParseUnifiedDiff() error = %v", err)
			}
			if len(d.Files) != tt.files || d.AddedLines() != tt.added || d.DeletedLines() != tt.deleted {
				t.Fatalf("got %d files, +%d -%d; want %d files, +%d -%d",
					len(d.Files), d.AddedLines(), d.DeletedLines(), tt.files, tt.added, tt.deleted)
			}
		})
	}
}

func TestParseIndexLineModes(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name  string
		patch string
		want  FileChange
	}{
		{
			name: "changed symlink target",
			patch: "diff --git a/link b/link\nindex 12a8d8a..9b40195 120000\n--- a/link\n+++ b/link\n@@ -1 +1 @@\n" +
				"-target1\n\\ No newline at end of file\n+../../etc/passwd\n\\ No newline at end of file\n",
			want: FileChange{Path: "link", Special: "symlink", Deleted: 1, Added: []Line{{1, "../../etc/passwd"}}},
		},
		{
			name: "changed submodule pointer",
			patch: "diff --git a/mod b/mod\nindex ec39edd..3f1a831 160000\n--- a/mod\n+++ b/mod\n@@ -1 +1 @@\n" +
				"-Subproject commit ec39edd483e37a7e26fe9751351a02d15e8374f3\n+Subproject commit 3f1a8319c252c18838d969239a6237f6336a586d\n",
			want: FileChange{Path: "mod", Special: "submodule", Deleted: 1, Added: []Line{{1, "Subproject commit 3f1a8319c252c18838d969239a6237f6336a586d"}}},
		},
		{
			name: "full-index regular file",
			patch: "diff --git a/f b/f\nindex " + strings.Repeat("a", 40) + ".." + strings.Repeat("b", 40) + " 100644\n" +
				"--- a/f\n+++ b/f\n@@ -1 +1 @@\n-a\n+b\n",
			want: FileChange{Path: "f", Deleted: 1, Added: []Line{{1, "b"}}},
		},
		{
			name:  "index without mode",
			patch: "diff --git a/f b/f\nindex 1234..abcd\n--- a/f\n+++ b/f\n@@ -1 +1 @@\n-a\n+b\n",
			want:  FileChange{Path: "f", Deleted: 1, Added: []Line{{1, "b"}}},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			d, err := ParseUnifiedDiff(tt.patch)
			if err != nil {
				t.Fatalf("ParseUnifiedDiff() error = %v", err)
			}
			if len(d.Files) != 1 || !reflect.DeepEqual(d.Files[0], tt.want) {
				t.Fatalf("got %#v, want %#v", d.Files, tt.want)
			}
		})
	}
}

func TestParseRejectsOddSections(t *testing.T) {
	t.Parallel()
	const hdr = "diff --git a/x b/x\n--- a/x\n+++ b/x\n"
	tests := []struct {
		name  string
		patch string
	}{
		{"index abc", "diff --git a/x b/x\nindex abc\n"},
		{"index non-hex", "diff --git a/x b/x\nindex zz..11\n"},
		{"index hash too short", "diff --git a/x b/x\nindex 123..abcd\n"},
		{"index hash too long", "diff --git a/x b/x\nindex " + strings.Repeat("a", 65) + "..abcd\n"},
		{"index empty hash", "diff --git a/x b/x\nindex ..abcd\n"},
		{"index bad mode", "diff --git a/x b/x\nindex 1234567..89abcde 1000\n"},
		{"index trailing text", "diff --git a/x b/x\nindex 1234567..89abcde 100644 extra\n"},
		{"index bare", "diff --git a/x b/x\nindex \n"},
		{"bare section", "diff --git a/x b/x\n"},
		{"index only section", "diff --git a/x b/x\nindex 1111111..2222222 100644\n"},
		{"file headers without hunk", hdr},
		{"file headers with index, no hunk", "diff --git a/x b/x\nindex 1111111..2222222 100644\n--- a/x\n+++ b/x\n"},
		{"zero-count hunk", hdr + "@@ -0,0 +0,0 @@\n"},
		{"bare section between files", "diff --git a/y b/y\n--- a/y\n+++ b/y\n@@ -1 +1 @@\n-a\n+b\ndiff --git a/x b/x\n"},
		{"same hunk twice", hdr + "@@ -1 +1 @@\n-a\n+b\n@@ -1 +1 @@\n-a\n+b\n"},
		{"overlapping old side", hdr + "@@ -1,3 +1,3 @@\n a\n-b\n+B\n c\n@@ -3,2 +10,2 @@\n c\n-d\n+D\n"},
		{"overlapping new side", hdr + "@@ -1,3 +1,3 @@\n a\n-b\n+B\n c\n@@ -10,2 +3,2 @@\n c\n-d\n+D\n"},
		{"hunks out of order", hdr + "@@ -10 +10 @@\n-a\n+b\n@@ -2 +2 @@\n-a\n+b\n"},
		{"zero-count inserts at same point", hdr + "@@ -5,0 +6 @@\n+a\n@@ -5,0 +7 @@\n+b\n"},
		{"new file hunk removes a line", "diff --git a/x b/x\nnew file mode 100644\n--- /dev/null\n+++ b/x\n@@ -1 +1 @@\n-a\n+b\n"},
		{"deleted file hunk adds a line", "diff --git a/x b/x\ndeleted file mode 100644\n--- a/x\n+++ /dev/null\n@@ -1 +1 @@\n-a\n+b\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := ParseUnifiedDiff(tt.patch)
			if err == nil {
				t.Fatalf("ParseUnifiedDiff() = %#v, want error", got)
			}
			if !strings.Contains(err.Error(), "line ") {
				t.Fatalf("error %q does not name a line", err)
			}
		})
	}
}
